public static METClaimCustFreeTextInvoicePostedBusinessEventContract newFromCustInvoiceJour(CustInvoiceJour _custInvoiceJour)
{
    var contract = new METClaimCustFreeTextInvoicePostedBusinessEventContract();
    contract.initialize(_custInvoiceJour);

    return contract;
}

